mkdir -p inspect cmd/debuginspect && cat > inspect/inspect.go <<'EOF'
// Package inspect deeply pretty-prints arbitrary Go values for debugging.
package inspect

import (
	"io"

	"github.com/davecgh/go-spew/spew"
)

// config is tuned for inspection: deterministic map ordering, pointer
// addresses shown, and circular references detected rather than looped.
var config = spew.ConfigState{
	Indent:                  "  ",
	SortKeys:                true,
	DisablePointerAddresses: false,
	DisableCapacities:       false,
	ContinueOnMethod:        true,
	SpewKeys:                true,
}

// Sdump returns a deep, human-readable dump of all values.
func Sdump(values ...any) string { return config.Sdump(values...) }

// Fdump writes a deep dump of all values to w.
func Fdump(w io.Writer, values ...any) { config.Fdump(w, values...) }

// Dump writes a deep dump of all values to stdout.
func Dump(values ...any) { config.Dump(values...) }
EOF
cat > inspect/inspect_test.go <<'EOF'
package inspect

import (
	"strings"
	"testing"
)

type node struct {
	Name     string
	Children []*node
	Parent   *node
	meta     map[string]int
}

func TestSdumpNestedAndCircular(t *testing.T) {
	root := &node{Name: "root", meta: map[string]int{"b": 2, "a": 1}}
	child := &node{Name: "child", Parent: root}
	root.Children = append(root.Children, child)

	out := Sdump(root)
	for _, want := range []string{`"root"`, `"child"`, "already shown", `"a": (int) 1`} {
		if !strings.Contains(out, want) {
			t.Errorf("output missing %q:\n%s", want, out)
		}
	}
	if strings.Index(out, `"a"`) > strings.Index(out, `"b"`) {
		t.Errorf("map keys not sorted:\n%s", out)
	}
}
EOF
cat > cmd/debuginspect/main.go <<'EOF'
// Command debuginspect demonstrates deep pretty-printing of Go values.
package main

import (
	"time"

	"debuginspect/inspect"
)

type Config struct {
	Name    string
	Tags    []string
	Limits  map[string]int
	Created time.Time
	Next    *Config
}

func main() {
	c := &Config{
		Name:    "example",
		Tags:    []string{"a", "b"},
		Limits:  map[string]int{"cpu": 2, "mem": 512},
		Created: time.Unix(0, 0).UTC(),
	}
	c.Next = c // circular reference is handled safely
	inspect.Dump(c)
}
EOF
